# Initially generated by GitHub Copilot.
"""Render a syntax-colored JSON snippet slide via Playwright browser screenshot.

Generates an HTML page with VS Code Dark+ colors and a CSS gradient background,
then uses Playwright/Chromium to screenshot it at exact slide dimensions.

This approach lets the browser handle font shaping and Unicode combining marks
correctly, avoiding the mark-collision artifacts of Pillow-based text rendering.
"""

import base64
import pathlib

from pygments import lex
from pygments.lexers import JsonLexer
from pygments.token import Token

from slide_generator import slide_render

# VS Code Dark+ colors (hex, for CSS)
_COLOR_KEY = "#9cdcfe"  # light blue — JSON keys
_COLOR_STRING = "#ce9178"  # warm orange — string values
_COLOR_NUMBER = "#b5cea8"  # light green — numbers
_COLOR_KEYWORD = "#569cd6"  # blue — true/false/null
_COLOR_PUNCT = "#d4d4d4"  # light gray — punctuation & whitespace

_TOKEN_CLASS_BY_COLOR = {
    _COLOR_KEY: "tok-key",
    _COLOR_STRING: "tok-string",
    _COLOR_NUMBER: "tok-number",
    _COLOR_KEYWORD: "tok-keyword",
    _COLOR_PUNCT: "tok-punct",
}

_TOKEN_CLASSES_CSS = """
    .tok-key { color: #9cdcfe; }
    .tok-string { color: #ce9178; }
    .tok-number { color: #b5cea8; }
    .tok-keyword { color: #569cd6; }
    .tok-punct { color: #d4d4d4; }
    .heb {
        unicode-bidi: isolate;
        direction: rtl;
    }
    .pointed {
        font-feature-settings: 'ss03';
    }
    .hl-bg {
        background-color: rgba(255,210,0,0.35);
        border-radius: 3px;
    }
    .paseq-bold {
        font-weight: bold;
    }
    .variant-gray {
        color: Gray;
    }"""

_TAAMEY_FONT = pathlib.Path.home() / "AppData/Local/Microsoft/Windows/Fonts/Taamey.ttf"
_FONT_SIZE_PX = 48


def _token_color(ttype) -> str:
    if ttype is Token.Name.Tag:
        return _COLOR_KEY
    if ttype in Token.Literal.String:
        return _COLOR_STRING
    if ttype in Token.Literal.Number:
        return _COLOR_NUMBER
    if ttype in Token.Keyword:
        return _COLOR_KEYWORD
    return _COLOR_PUNCT


def _has_pointing(text: str) -> bool:
    """Return True if text contains Hebrew combining marks (nikud or taamim)."""
    return any("\u0591" <= ch <= "\u05c7" for ch in text)


def _has_hebrew(text: str) -> bool:
    """Return True if text contains any Hebrew letter."""
    return any("\u05d0" <= ch <= "\u05ea" or "\ufb1d" <= ch <= "\ufb4e" for ch in text)


def _token_class_for_color(color: str) -> str:
    """Return CSS class name for a token color."""
    return _TOKEN_CLASS_BY_COLOR[color]


def _style_attr(styles: list[str]) -> str:
    """Return an HTML style attribute (leading space) for CSS declarations."""
    if not styles:
        return ""
    return f' style="{";".join(styles)}"'


def _highlight_companion_html(html: str, highlight_text: str) -> str:
    """Return html with the first occurrence of highlight_text wrapped in a .hl span."""
    return html.replace(highlight_text, f'<span class="hl">{highlight_text}</span>', 1)


def _highlight_sub_ranges(json_text: str, hl_start: int, hl_end: int) -> list:
    """Compute (char_start, char_end) sub-ranges within [hl_start, hl_end) that get
    yellow background.  Leading whitespace on continuation lines (after each embedded
    newline) is excluded — i.e. only the non-indent content of each line is highlighted.
    Returns a list of (start, end) int pairs.
    """
    text = json_text[hl_start:hl_end]
    lines = text.split("\n")
    ranges = []
    pos = hl_start
    for i, line in enumerate(lines):
        if i > 0:
            pos += 1  # skip the \n itself
        if i == 0:
            if line:
                ranges.append((pos, pos + len(line)))
        else:
            stripped = line.lstrip(" \t")
            indent_len = len(line) - len(stripped)
            if stripped:
                ranges.append((pos + indent_len, pos + len(line)))
        pos += len(line)
    return ranges


def _tokenize_with_splits(json_text: str, split_points: set) -> list:
    """Tokenize JSON via Pygments, splitting tokens at the given extra character
    positions.  Returns a list of (char_start, char_end, text, color) tuples.
    Tokenising once with all split points collected up-front means every step's
    highlight boundary falls exactly at a span boundary.
    """
    spans = []
    pos = 0
    for ttype, value in lex(json_text, JsonLexer()):
        color = _token_color(ttype)
        tok_end = pos + len(value)
        tok_splits = sorted(p for p in split_points if pos < p < tok_end)
        sub_start = pos
        for sp in tok_splits:
            sub_text = json_text[sub_start:sp]
            if sub_text:
                spans.append((sub_start, sp, sub_text, color))
            sub_start = sp
        sub_text = json_text[sub_start:tok_end]
        if sub_text:
            spans.append((sub_start, tok_end, sub_text, color))
        pos = tok_end
    return spans


def _span_html_with_class(
    text: str, color: str, font_size_px: int, pointed_scale: float, cls: str
) -> str:
    """Return HTML for one atomic span carrying a CSS class string.
    Uses ``unicode-bidi:isolate`` instead of a wrapping <bdi> element so that a
    single element can be targeted by both display and background-color CSS rules.
    """
    escaped = text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    classes = [_token_class_for_color(color)]
    styles = []
    if _has_hebrew(text):
        classes.append("heb")
    if _has_pointing(text) and pointed_scale != 1.0:
        classes.append("pointed")
        styles.append(f"font-size:{round(font_size_px * pointed_scale)}px")
    if cls:
        classes.extend(cls.split())
    cls_attr = f' class="{" ".join(classes)}"'
    return f"<span{cls_attr}{_style_attr(styles)}>{escaped}</span>"


def _one_span(
    value: str,
    color: str,
    font_size_px: int,
    pointed_scale: float,
    hl_bg: bool,
    zoom: bool,
) -> str:
    """Return the HTML span(s) for a single pygments token value."""
    escaped = value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    classes = [_token_class_for_color(color)]
    styles = []
    if hl_bg:
        classes.append("hl-bg")
    if _has_hebrew(value):
        classes.append("heb")
    if zoom:
        size = round(font_size_px * pointed_scale * 2)
        classes.append("pointed")
        styles.append(f"font-size:{size}px")
    elif pointed_scale != 1.0 and _has_pointing(value):
        classes.append("pointed")
        styles.append(f"font-size:{round(font_size_px * pointed_scale)}px")
    cls_attr = f' class="{" ".join(classes)}"'
    return f"<span{cls_attr}{_style_attr(styles)}>{escaped}</span>"


def _build_html(
    json_text: str,
    top_rgb: tuple,
    bot_rgb: tuple,
    font_size_px: int,
    companion_image_uri: str = None,
    layout: str = "column",
    pointed_scale: float = 2.0,
    companion_first: bool = False,
    companion_html: str = None,
    highlight_text: str = None,
    highlight_occurrence: int = 1,
    companion_highlight_html: str = None,
) -> str:
    W, H = slide_render.W, slide_render.H
    font_uri = _TAAMEY_FONT.as_uri()

    # Tokenize the whole JSON once, then use character offsets to decide highlight.
    # This avoids re-tokenizing fragments (which changes color assignments).
    if highlight_text:
        start = 0
        for _ in range(highlight_occurrence):
            hl_start = json_text.index(highlight_text, start)
            start = hl_start + 1
        hl_end = hl_start + len(highlight_text)
    else:
        hl_start = -1
        hl_end = -1

    code_spans = []
    zoom_spans = []
    pos = 0
    for ttype, value in lex(json_text, JsonLexer()):
        color = _token_color(ttype)
        tok_end = pos + len(value)
        # Does this token overlap the highlight range?
        if highlight_text and pos < hl_end and tok_end > hl_start:
            # Split the token into up-to-three parts: before-hl, inside-hl, after-hl.
            pre = value[: max(0, hl_start - pos)]
            mid = value[max(0, hl_start - pos) : min(len(value), hl_end - pos)]
            post = value[min(len(value), hl_end - pos) :]
            if pre:
                code_spans.append(
                    _one_span(
                        pre, color, font_size_px, pointed_scale, hl_bg=False, zoom=False
                    )
                )
            if mid:
                mid_abs_start = max(pos, hl_start)
                cur = 0
                for rstart, rend in _highlight_sub_ranges(
                    json_text, mid_abs_start, min(tok_end, hl_end)
                ):
                    s = rstart - mid_abs_start
                    e = rend - mid_abs_start
                    if s > cur:
                        code_spans.append(
                            _one_span(
                                mid[cur:s],
                                color,
                                font_size_px,
                                pointed_scale,
                                hl_bg=False,
                                zoom=False,
                            )
                        )
                    code_spans.append(
                        _one_span(
                            mid[s:e],
                            color,
                            font_size_px,
                            pointed_scale,
                            hl_bg=True,
                            zoom=False,
                        )
                    )
                    cur = e
                if cur < len(mid):
                    code_spans.append(
                        _one_span(
                            mid[cur:],
                            color,
                            font_size_px,
                            pointed_scale,
                            hl_bg=False,
                            zoom=False,
                        )
                    )
                zoom_spans.append(
                    _one_span(
                        mid, color, font_size_px, pointed_scale, hl_bg=False, zoom=True
                    )
                )
            if post:
                code_spans.append(
                    _one_span(
                        post,
                        color,
                        font_size_px,
                        pointed_scale,
                        hl_bg=False,
                        zoom=False,
                    )
                )
        else:
            code_spans.append(
                _one_span(
                    value, color, font_size_px, pointed_scale, hl_bg=False, zoom=False
                )
            )
        pos = tok_end

    code_html = "".join(code_spans)
    zoom_html = "".join(zoom_spans)

    tr, tg, tb = top_rgb
    br, bg, bb = bot_rgb

    if layout == "row":
        layout_css = """
  body {
    display: flex;
    flex-direction: row;
    align-items: stretch;
  }
  .col {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 60px;
    overflow: hidden;
  }
  img.companion {
    width: 90%;
    height: auto;
  }
  .companion-html {
    font-family: 'Taamey', serif;
    direction: rtl;
    font-size: 80px;
    line-height: 2.0;
    text-align: right;
    color: white;
    width: 100%;
  }
  .hl {
    background-color: rgba(255, 210, 0, 0.4);
    border-radius: 3px;
  }"""
        if companion_html is not None:
            _hl_key = (
                companion_highlight_html
                if companion_highlight_html is not None
                else highlight_text
            )
            hl_companion = (
                _highlight_companion_html(companion_html, _hl_key)
                if _hl_key
                else companion_html
            )
            companion_content = f'<div class="companion-html">{hl_companion}</div>'
        elif companion_image_uri:
            companion_content = f'<img class="companion" src="{companion_image_uri}">'
        else:
            companion_content = ""
        if highlight_text:
            body_html = (
                f'<div class="col" style="flex:2;flex-direction:column;justify-content:space-between;align-items:flex-start">'
                f"<pre>{zoom_html}</pre>"
                f"{companion_content}"
                f"</div>"
                f'<div class="col" style="flex:2;justify-content:flex-start"><pre>{code_html}</pre></div>'
            )
        else:
            body_html = (
                f'<div class="col">{companion_content}</div><div class="col" style="justify-content:flex-start"><pre>{code_html}</pre></div>'
                if companion_first
                else f'<div class="col"><pre>{code_html}</pre></div><div class="col">{companion_content}</div>'
            )
    else:
        layout_css = """
  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 60px;
  }
  img.companion {
    max-width: 70%;
    height: auto;
  }"""
        companion_tag = (
            f'<img class="companion" src="{companion_image_uri}">'
            if companion_image_uri
            else ""
        )
        body_html = f"<pre>{code_html}</pre>{companion_tag}"

    return f"""<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  @font-face {{
    font-family: 'Taamey';
    src: url('{font_uri}');
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  html, body {{
    width: {W}px;
    height: {H}px;
    overflow: hidden;
    background: linear-gradient(to bottom,
      rgb({tr},{tg},{tb}),
      rgb({br},{bg},{bb}));
  }}
{layout_css}
{_TOKEN_CLASSES_CSS}
  pre {{
    font-family: 'Taamey', 'Consolas', monospace;
    font-size: {font_size_px}px;
    line-height: 1.8;
    direction: ltr;
    unicode-bidi: normal;
    white-space: pre;
  }}
</style>
</head>
<body>{body_html}</body>
</html>"""


def _build_multistep_html(
    json_text: str,
    steps: list,
    top_rgb: tuple,
    bot_rgb: tuple,
    font_size_px: int,
    pointed_scale: float,
    companion_html: str,
) -> str:
    """Build one HTML document for all steps; CSS + a JS attribute change drives each step.

    The JSON is tokenised once.  All highlight-range boundaries are collected up-front
    so tokens are split at every needed position.  Each atomic sub-span receives classes:

      hl-<n>   – this span gets yellow background when step n is active
      zm-<n>   – this span is visible in the zoom panel when step n is active

    Zoom = highlighted text shown large.  The zoom panel is the same <pre> HTML as the
    main panel (JS copies innerHTML); per-step CSS makes non-zm spans display:none and
    scales zm spans up.  Highlighting and zoom are thus the same concept expressed in two
    CSS properties — no separate per-step token walk is needed.

    A single <pre id="main"> holds the code for the right column.
    JS copies it into <pre id="zoom"> then sets body[data-step].

    To regenerate after Psalm 5v9 mpplus.json changes, re-run:
        .venv\\Scripts\\python.exe py\\main_slide_generator.py render-slides --deck mam-is-a-dataset psalm-5v9-mpplus-steps
    """
    W, H = slide_render.W, slide_render.H
    font_uri = _TAAMEY_FONT.as_uri()
    tr, tg, tb = top_rgb
    br, bg, bb = bot_rgb

    # 1. For each step compute:
    #    hl_full – (hl_start, hl_end) full range for zoom (or None if no highlight)
    #    sub_ranges – list of (start, end) sub-ranges that get yellow bg (no-indent rule)
    step_info = []
    for spec in steps:
        hl_text = spec.get("highlight_text")
        if not hl_text:
            step_info.append((None, []))
            continue
        occ = spec.get("highlight_occurrence", 1)
        start = 0
        for _ in range(occ):
            hl_start = json_text.index(hl_text, start)
            start = hl_start + 1
        hl_end = hl_start + len(hl_text)
        step_info.append(
            ((hl_start, hl_end), _highlight_sub_ranges(json_text, hl_start, hl_end))
        )

    # 2. Collect all character split points from every highlight boundary.
    split_points = set()
    for hl_full, sub_ranges in step_info:
        if hl_full is not None:
            split_points.update(hl_full)
        for rstart, rend in sub_ranges:
            split_points.add(rstart)
            split_points.add(rend)

    # 3. Tokenise once with all split points → atomic sub-spans.
    spans = _tokenize_with_splits(json_text, split_points)

    # 4. For each span compute which steps highlight / zoom it.
    span_hl = [set() for _ in spans]
    span_zm = [set() for _ in spans]
    for step_idx, (hl_full, sub_ranges) in enumerate(step_info):
        if hl_full is None:
            continue
        hl_start, hl_end = hl_full
        for i, (cstart, cend, _text, _color) in enumerate(spans):
            if cstart >= hl_start and cend <= hl_end:
                span_zm[i].add(step_idx)
            for rstart, rend in sub_ranges:
                if cstart >= rstart and cend <= rend:
                    span_hl[i].add(step_idx)
                    break

    # 5. Build the single <pre> inner HTML shared by both #main and #zoom.
    pre_parts = []
    for i, (cstart, cend, text, color) in enumerate(spans):
        hl_cls = " ".join(f"hl-{s}" for s in sorted(span_hl[i]))
        zm_cls = " ".join(f"zm-{s}" for s in sorted(span_zm[i]))
        cls = " ".join(filter(None, [hl_cls, zm_cls]))
        pre_parts.append(
            _span_html_with_class(text, color, font_size_px, pointed_scale, cls)
        )
    pre_html = "".join(pre_parts)

    # 6. Build per-step CSS rules.
    zoom_font_size = round(font_size_px * pointed_scale * 2)
    css_rules = []
    for step_idx, (hl_full, _sub) in enumerate(step_info):
        spec = steps[step_idx]
        companion_hl_ids = spec.get("companion_hl_ids")
        if hl_full is not None:
            css_rules.append(
                f'body[data-step="{step_idx}"] #main .hl-{step_idx} '
                f"{{ background-color: rgba(255,210,0,0.35); border-radius: 3px; }}"
            )
            css_rules.append(
                f'body[data-step="{step_idx}"] #zoom {{ display: block; }}'
            )
            css_rules.append(
                f'body[data-step="{step_idx}"] #zoom .zm-{step_idx} '
                f"{{ display: inline; font-size: {zoom_font_size}px !important; "
                f"font-feature-settings: 'ss03'; }}"
            )
        if companion_hl_ids:
            for hl_id in companion_hl_ids:
                css_rules.append(
                    f'body[data-step="{step_idx}"] [data-hl-id="{hl_id}"] '
                    f"{{ background-color: rgba(255,210,0,0.4); border-radius: 3px; display: inline; }}"
                )

    extra_css = ("\n  " + "\n  ".join(css_rules)) if css_rules else ""
    return f"""<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  @font-face {{
    font-family: 'Taamey';
    src: url('{font_uri}');
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  html, body {{
    width: {W}px;
    height: {H}px;
    overflow: hidden;
    background: linear-gradient(to bottom,
      rgb({tr},{tg},{tb}),
      rgb({br},{bg},{bb}));
  }}
  body {{
    display: flex;
    flex-direction: row;
    align-items: stretch;
  }}
  #left-col {{
    flex: 2;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    padding: 60px;
  }}
  #right-col {{
    flex: 2;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    padding: 60px;
    overflow: hidden;
  }}
  #zoom {{
    display: none;
    flex-shrink: 0;
  }}
  #zoom span {{
    display: none;
  }}
  #companion-wrapper {{
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
  }}
  .companion-html {{
    font-family: 'Taamey', serif;
    direction: rtl;
    font-size: 80px;
    line-height: 2.0;
    text-align: right;
    color: white;
    width: 100%;
  }}
  [data-hl-id="rs1"], [data-hl-id="rs2"] {{
    display: none;
  }}
{_TOKEN_CLASSES_CSS}
  pre {{
    font-family: 'Taamey', 'Consolas', monospace;
    font-size: {font_size_px}px;
    line-height: 1.8;
    direction: ltr;
    unicode-bidi: normal;
    white-space: pre;
  }}{extra_css}
</style>
</head>
<body data-step="0">
  <div id="left-col">
    <pre id="zoom"></pre>
    <div id="companion-wrapper">
      <div class="companion-html">{companion_html or ""}</div>
    </div>
  </div>
  <div id="right-col">
    <pre id="main">{pre_html}</pre>
  </div>
<script>
(function () {{
  var main = document.getElementById('main');
  var zoom = document.getElementById('zoom');
  zoom.innerHTML = main.innerHTML;
  var n = parseInt(new URLSearchParams(window.location.search).get('step') || '0', 10);
  document.body.dataset.step = String(n);
}})();
</script>
</body>
</html>"""


def render_json_snippet_browser_steps(
    images_dir: pathlib.Path,
    deck_name: str,
    json_path: pathlib.Path,
    slide_base_name: str,
    steps: list,
    top_rgb: tuple = (13, 94, 87),
    bot_rgb: tuple = (8, 61, 56),
    font_size_px: int = _FONT_SIZE_PX,
    pointed_scale: float = 2.0,
    companion_html_path: pathlib.Path = None,
    html_only: bool = False,
) -> None:
    """Build one multi-step interactive HTML and screenshot each step as a PNG.

    The interactive HTML is saved alongside the JSON source as
    ``slide-{slide_base_name}-interactive.html``.  Open it in a browser with
    ``?step=N`` to view any step.  Playwright then navigates to each
    ``?step=N`` URL and saves ``slide-{slide_base_name}-step-{N}.png``.

    Pass ``html_only=True`` to skip the Playwright screenshot pass and only
    (re)generate the interactive HTML file.  Useful for rapid iteration on
    layout and RTL rendering without waiting for PNG generation.
    """
    from playwright.sync_api import sync_playwright

    companion_html = None
    if companion_html_path is not None:
        companion_html = pathlib.Path(companion_html_path).read_text(encoding="utf-8")

    json_text = json_path.read_text(encoding="utf-8")
    html = _build_multistep_html(
        json_text,
        steps,
        top_rgb,
        bot_rgb,
        font_size_px,
        pointed_scale,
        companion_html,
    )

    html_path = json_path.parent.resolve() / f"slide-{slide_base_name}-interactive.html"
    html_path.write_text(html, encoding="utf-8")
    print(f"Saved {html_path}")

    if html_only:
        return

    images_dir.mkdir(parents=True, exist_ok=True)
    html_uri = html_path.as_uri()
    with sync_playwright() as p:
        browser = p.chromium.launch()
        page = browser.new_page(
            viewport={"width": slide_render.W, "height": slide_render.H}
        )
        for step_idx, _spec in enumerate(steps):
            step_name = f"{slide_base_name}-step-{step_idx}"
            page.goto(f"{html_uri}?step={step_idx}")
            page.wait_for_load_state("networkidle")
            dest = images_dir / f"slide-{step_name}.png"
            page.screenshot(path=str(dest))
            slide_render.write_provenance(dest, deck_name, step_name)
            print(f"Saved {dest}")
        browser.close()


def render_json_snippet_browser(
    images_dir: pathlib.Path,
    deck_name: str,
    json_path: pathlib.Path,
    slide_name: str,
    top_rgb: tuple = (13, 94, 87),
    bot_rgb: tuple = (8, 61, 56),
    font_size_px: int = _FONT_SIZE_PX,
    companion_image_path: pathlib.Path = None,
    layout: str = "column",
    pointed_scale: float = 2.0,
    companion_first: bool = False,
    companion_html_path: pathlib.Path = None,
    highlight_text: str = None,
    highlight_occurrence: int = 1,
    companion_highlight_html: str = None,
) -> None:
    """Render a syntax-colored JSON snippet slide via Playwright/Chromium screenshot."""
    from playwright.sync_api import sync_playwright

    companion_image_uri = None
    if companion_image_path is not None:
        img_bytes = pathlib.Path(companion_image_path).read_bytes()
        b64 = base64.b64encode(img_bytes).decode("ascii")
        companion_image_uri = f"data:image/png;base64,{b64}"

    companion_html = None
    if companion_html_path is not None:
        companion_html = pathlib.Path(companion_html_path).read_text(encoding="utf-8")

    json_text = json_path.read_text(encoding="utf-8")
    html = _build_html(
        json_text,
        top_rgb,
        bot_rgb,
        font_size_px,
        companion_image_uri,
        layout,
        pointed_scale,
        companion_first,
        companion_html=companion_html,
        highlight_text=highlight_text,
        highlight_occurrence=highlight_occurrence,
        companion_highlight_html=companion_highlight_html,
    )

    html_dest = json_path.parent.resolve() / f"slide-{slide_name}.html"
    html_dest.write_text(html, encoding="utf-8")

    tmp_path = html_dest
    with sync_playwright() as p:
        browser = p.chromium.launch()
        page = browser.new_page(
            viewport={"width": slide_render.W, "height": slide_render.H}
        )
        page.goto(tmp_path.as_uri())
        page.wait_for_load_state("networkidle")
        dest = images_dir / f"slide-{slide_name}.png"
        dest.parent.mkdir(parents=True, exist_ok=True)
        page.screenshot(path=str(dest))
        browser.close()

    slide_render.write_provenance(dest, deck_name, slide_name)
    print(f"Saved {dest} ({slide_render.W}, {slide_render.H})")
